insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('365d08f7-d0fb-5e45-ae9b-f2faf56c11d8', '3bea883a-9020-5c93-9cf2-9c4fdfcc70a8', 'PREHAB — Developmental Positions (7wk)', 'Functional', 'Beginner', 7, '{"1": "Supine week. Ground floor of the progression: own breathing, pelvic control, and core-limb dissociation with full floor support. 2-3 sessions/week. Rule for the whole program: advance to the next position only when this one is controlled, symmetrical, and pain-free (0-5/10 max, nothing sharp).", "2": "Sidelying week. Gravity now challenges the lateral system: glute med, adductors, cuff, and lateral trunk wake up here.", "3": "Quadruped week. Hands-and-knees: spine moves segmentally, shoulder blades learn to serve a weight-bearing arm, and the trunk resists rotation with a smaller base.", "4": "Tall-kneeling week. Knees-only base removes the ankles from the equation \u2014 hips and trunk must do the stabilizing. Band or cable tension shows up in earnest this week.", "5": "Half-kneeling week. The classic in-between: one hip flexed, one extended \u2014 the position golf, throwing, and sprinting are built from. Narrow the stance to progress.", "6": "Standing week. Full upright stance against band/cable tension, plus single-leg balance. This is where the gym meets real life.", "7": "Split-stance week \u2014 graduation. The most sport-specific base: staggered feet, rotation control, single-leg strength. Finishing here means the client is ready for loaded training in every position that matters."}'::jsonb) on conflict (id) do nothing;
